    // splitPathInRoot splits a path into components
    // and joins it with the given prefix and suffix.
    //
    // The path is relative to a Root, and must not be
    // absolute, volume-relative, or "".
    //
    // "." components are removed, except in the last component.
    //
    // endsInSlash reports whether the path ends in one or more slashes.
    std::tuple<gocpp::slice<gocpp::string>, bool, gocpp::error> splitPathInRoot(gocpp::string s, gocpp::slice<gocpp::string> prefix, gocpp::slice<gocpp::string> suffix)
    {
        gocpp::slice<gocpp::string> _1;
        bool endsInSlash;
        gocpp::error err;
        if(len(s) == 0)
        {
            return {nullptr, false, errors::New("empty path"_s)};
        }
        if(IsPathSeparator(s[0]))
        {
            return {nullptr, false, errPathEscapes};
        }

        if(mocklib::GOOS == "windows"_s)
        {
            // Windows cleans paths before opening them.
            std::tie(s, err) = rootCleanPath(s, prefix, suffix);
            if(err != nullptr)
            {
                return {nullptr, false, err};
            }
            prefix = nullptr;
            suffix = nullptr;
        }

        auto parts = slices::Clone(prefix);
        auto [i, j] = std::tuple{0, 1};
        for(; ; )
        {
            if(j < len(s) && ! IsPathSeparator(s[j]))
            {
                // Keep looking for the end of this component.
                j++;
                continue;
            }
            parts = append(parts, s.make_slice(i, j));
            // Advance to the next component, or end of the path.
            auto partEnd = j;
            for(; j < len(s) && IsPathSeparator(s[j]); )
            {
                j++;
            }
            if(j == len(s))
            {
                // If this is the last path component,
                // check for any trailing path separators.
                if(len(s.make_slice(partEnd)) > 0)
                {
                    endsInSlash = true;
                }
                break;
            }
            if(parts[len(parts) - 1] == "."_s)
            {
                // Remove "." components, except at the end.
                parts = parts.make_slice(0, len(parts) - 1);
            }
            i = j;
        }
        if(len(suffix) > 0 && len(parts) > 0 && parts[len(parts) - 1] == "."_s)
        {
            // Remove a trailing "." component if we're joining to a suffix.
            parts = parts.make_slice(0, len(parts) - 1);
        }
        parts = append(parts, suffix);
        return {parts, endsInSlash, nullptr};
    }

